      // source-bound selection must not receive page URL/title context.
      const traceTabInfo = await this._getTabUrlTitle(tabId);
      plannerTabInfo = selectionOnly || standaloneChatRun ? { tabUrl: '', tabTitle: '' } : traceTabInfo;
